import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CRfKVJQk.js";const p=JSON.parse(`{"title":"How it works","description":"You don't need this page to use the library, but two minutes here make every other page easier.","frontmatter":{"description":"You don't need this page to use the library, but two minutes here make every other page easier.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/guide/how-it-works"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/guide/how-it-works"}],["meta",{"property":"og:title","content":"How it works · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"You don't need this page to use the library, but two minutes here make every other page easier."}],["meta",{"name":"twitter:title","content":"How it works · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"You don't need this page to use the library, but two minutes here make every other page easier."}]]},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"guide/how-it-works.md"}`),i={name:"guide/how-it-works.md"};function s(n,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h1><p>You don&#39;t need this page to use the library, but two minutes here make every other page easier.</p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Glass shows a blurred, bent copy of <strong>what&#39;s behind it</strong>. A normal view can&#39;t see behind itself: it only knows how to draw its own pixels. So every platform needs a different trick.</p><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h2><ol><li>You wrap the content the glass should see in a <a href="/react-native-glass-effect/components/glass-backdrop"><code>&lt;GlassBackdrop&gt;</code></a>.</li><li>The backdrop records what it draws into a GPU display list (a <code>RenderNode</code>). This isn&#39;t a screenshot: it&#39;s a list of drawing commands, cheap to replay.</li><li>Each glass view replays that list, lined up with its own position on screen, through a blur, a saturation step and, on Android 13+, a refraction shader written in AGSL.</li><li>The glass then draws its tint, rim light and border, and finally its children on top, sharp.</li></ol><p>When the content under the glass changes, or the glass moves, only the glass views that overlap the change redraw. Changes far away cost nothing.</p><p>On Android 7–11, GPU blur isn&#39;t available, so the library takes a snapshot of the backdrop, blurs it on the CPU and reuses it while it can.</p><h2 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS&quot;">​</a></h2><p>iOS can blur the real screen by itself, so by default the library uses Apple&#39;s own effect:</p><ul><li><strong>iOS 26+</strong>: <code>UIGlassEffect</code>, Apple&#39;s Liquid Glass.</li><li><strong>iOS 15–25</strong>: <code>UIVisualEffectView</code> system materials.</li></ul><p><code>&lt;GlassBackdrop&gt;</code> is a plain view on iOS in that mode. Keep it anyway: the same code then works on both platforms.</p><p>With <code>iosRenderer=&quot;shader&quot;</code>, iOS uses the library&#39;s own Metal renderer instead. It samples the backdrop like Android does, so the two platforms match and every prop works. See <a href="/react-native-glass-effect/features/ios-renderers">iOS renderers</a>.</p><h2 id="web" tabindex="-1">Web <a class="header-anchor" href="#web" aria-label="Permalink to &quot;Web&quot;">​</a></h2><p>The web build uses CSS <code>backdrop-filter: blur() saturate()</code> with your tint, border and corner radius. Refraction, chromatic aberration and touch lighting have no web equivalent, so those props are accepted and ignored. See <a href="/react-native-glass-effect/installation/web">Web installation</a>.</p><h2 id="materials-and-resolution" tabindex="-1">Materials and resolution <a class="header-anchor" href="#materials-and-resolution" aria-label="Permalink to &quot;Materials and resolution&quot;">​</a></h2><p>Every glass starts from a <strong>material</strong>, a named set of values (blur, tint, refraction, light, border…). The library resolves the final values in this order, last wins:</p><ol><li>The built-in material preset.</li><li>Your theme&#39;s overrides for that material (<a href="/react-native-glass-effect/components/glass-theme-provider"><code>GlassThemeProvider</code></a>).</li><li>The props on the component.</li><li><code>intensity</code> scales the effect strengths, and everything is clamped to safe ranges.</li></ol><p>The result is a set of flat numbers sent to native. Native never knows the word &quot;regular&quot;.</p><h2 id="quality" tabindex="-1">Quality <a class="header-anchor" href="#quality" aria-label="Permalink to &quot;Quality&quot;">​</a></h2><p><code>quality=&quot;auto&quot;</code> (the default) picks the best effect the device can afford: less on old or low-RAM phones, in battery saver, or when many glass views are on screen. See <a href="/react-native-glass-effect/features/quality">Quality and performance</a>.</p><h2 id="never-crash" tabindex="-1">Never crash <a class="header-anchor" href="#never-crash" aria-label="Permalink to &quot;Never crash&quot;">​</a></h2><p>Every failure has a fallback:</p><table tabindex="0"><thead><tr><th>Situation</th><th>What you get</th></tr></thead><tbody><tr><td>The shader fails to compile on a GPU</td><td>Blur without refraction</td></tr><tr><td>Capturing the backdrop fails</td><td>An opaque fallback surface</td></tr><tr><td>No backdrop on Android</td><td>An opaque fallback surface and one log line</td></tr><tr><td>Expo Go, tests, missing native code</td><td>A plain tinted view</td></tr><tr><td>Reduce Transparency is on</td><td>An opaque <code>fallbackColor</code> surface</td></tr></tbody></table><p>The full list is in the <a href="/react-native-glass-effect/architecture/05-edge-cases">edge-case table</a>.</p>',25)])])}const f=t(i,[["render",s]]);export{p as __pageData,f as default};
